    </MaintenanceFeature>
  </main>
</template>

<script setup>
import {computed} from 'vue'
import {useRouter} from 'vue-router'
import AppHeader from '@/components/appHeader/AppHeader.vue'
import MaintenanceFeature from '@/components/maintenance/MaintenanceFeature.vue'
import {openLoginDialog} from '@/utils/loginDialog.js'
import {SMART_DEFAULT_RULES,SMART_TEMPLATES,SMART_SORTS,copySmartRules,smartSummary} from '@/utils/smartPlaylists.js'
import {useSmartPlaylists} from '@/composables/useSmartPlaylists.js'
defineOptions({name:'SmartPlaylistsPage'})
const router=useRouter()
const {user,state,engine,dirty,validation}=useSmartPlaylists()
const rule=(key,value)=>engine.change({rules:{[key]:value}})
function minutes(key,value){rule(key,value===''?0:Math.round(Number(value)*60))}
const time=ms=>{if(!ms)return '—';const seconds=Math.floor(ms/1000);return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')}
const previewStale=computed(()=>state.previewSignature!==JSON.stringify(copySmartRules(state.rules)))
const saveStatus=computed(()=>state.conflict?'需要处理版本冲突':validation.value?'请完善当前条件':state.saving?'正在自动保存…':dirty.value?'等待保存…':'已自动保存')
</script>

